-- Finance organ -- generated by noctusai_lib.domain.finance.sql (do not hand-edit)

SET search_path = orbity, public;

-- Accounts (bank / cash / gateway wallets). One gateway account per (org, gateway).
CREATE TABLE IF NOT EXISTS orbity.fin_accounts (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id                UUID NOT NULL,
    name                  TEXT NOT NULL,
    kind                  TEXT NOT NULL CHECK (kind IN ('checking', 'savings', 'cash', 'gateway', 'credit_card', 'investment')),
    bank_code             TEXT,
    agency                TEXT,
    number                TEXT,
    opening_balance_cents BIGINT NOT NULL DEFAULT 0,
    opening_date          DATE,
    gateway               TEXT,
    active                BOOLEAN NOT NULL DEFAULT true,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (kind <> 'gateway' OR gateway IS NOT NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_accounts_gateway ON orbity.fin_accounts (org_id, gateway)
    WHERE kind = 'gateway';
CREATE INDEX IF NOT EXISTS idx_fin_accounts_org ON orbity.fin_accounts (org_id);
-- Accounting code (E21): the contador's reduced account code for this bank/cash/gateway account (free text, optional);
-- the Domínio export refuses to run while a used account has none.
ALTER TABLE orbity.fin_accounts ADD COLUMN IF NOT EXISTS accounting_code TEXT;
COMMENT ON TABLE orbity.fin_accounts IS 'tier:org';
ALTER TABLE orbity.fin_accounts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_accounts_select_own_org" ON orbity.fin_accounts;
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_accounts;
CREATE POLICY "service_role_bypass" ON orbity.fin_accounts FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON orbity.fin_accounts FROM PUBLIC, anon, authenticated;
GRANT ALL ON orbity.fin_accounts TO service_role;

-- Categories (tree). Unique (org, parent, lower(name)); defaults are seeded per org on first use.
CREATE TABLE IF NOT EXISTS orbity.fin_categories (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    parent_id   UUID REFERENCES orbity.fin_categories(id) ON DELETE RESTRICT,
    name        TEXT NOT NULL,
    direction   TEXT NOT NULL CHECK (direction IN ('income', 'expense', 'transfer')),
    is_default  BOOLEAN NOT NULL DEFAULT false,
    active      BOOLEAN NOT NULL DEFAULT true,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_categories_name ON orbity.fin_categories
    (org_id, COALESCE(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(name));
CREATE INDEX IF NOT EXISTS idx_fin_categories_parent ON orbity.fin_categories (parent_id);
-- DRE mapping (CONTRACT §10.3 / §10.5): additive and re-runnable (tables created by an older generator gain the columns).
-- dre_line NULL = unclassified (shown in its own block with a warning); behavior NULL = the line's default;
-- is_das marks the category that holds the DAS payable (routed by the store's tax regime).
ALTER TABLE orbity.fin_categories ADD COLUMN IF NOT EXISTS dre_line TEXT
    CHECK (dre_line IN ('gross_revenue', 'deductions', 'cost_of_sales', 'selling_expenses', 'administrative_expenses', 'other_operating', 'financial_revenue', 'financial_expenses', 'income_taxes', 'unclassified'));
ALTER TABLE orbity.fin_categories ADD COLUMN IF NOT EXISTS behavior TEXT
    CHECK (behavior IN ('variable', 'fixed'));
ALTER TABLE orbity.fin_categories ADD COLUMN IF NOT EXISTS is_das BOOLEAN NOT NULL DEFAULT false;
-- E21: the contador's reduced account code (free text, optional -- only the Domínio export needs it) and the MEI
-- activity group (comércio / indústria / serviços) the Relatório Mensal de Receitas Brutas splits revenue by.
ALTER TABLE orbity.fin_categories ADD COLUMN IF NOT EXISTS accounting_code TEXT;
ALTER TABLE orbity.fin_categories ADD COLUMN IF NOT EXISTS activity_kind TEXT
    CHECK (activity_kind IN ('comercio', 'industria', 'servicos'));
COMMENT ON TABLE orbity.fin_categories IS 'tier:org';
ALTER TABLE orbity.fin_categories ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_categories_select_own_org" ON orbity.fin_categories;
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_categories;
CREATE POLICY "service_role_bypass" ON orbity.fin_categories FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON orbity.fin_categories FROM PUBLIC, anon, authenticated;
GRANT ALL ON orbity.fin_categories TO service_role;

-- Cost centers (code unique per org).
CREATE TABLE IF NOT EXISTS orbity.fin_cost_centers (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    code        TEXT NOT NULL,
    name        TEXT NOT NULL,
    active      BOOLEAN NOT NULL DEFAULT true,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (org_id, code)
);
COMMENT ON TABLE orbity.fin_cost_centers IS 'tier:org';
ALTER TABLE orbity.fin_cost_centers ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_cost_centers_select_own_org" ON orbity.fin_cost_centers;
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_cost_centers;
CREATE POLICY "service_role_bypass" ON orbity.fin_cost_centers FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON orbity.fin_cost_centers FROM PUBLIC, anon, authenticated;
GRANT ALL ON orbity.fin_cost_centers TO service_role;

-- Recurrences: `template` is the entry shape; generation is idempotent on (recurrence_id, due_date).
CREATE TABLE IF NOT EXISTS orbity.fin_recurrences (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    template    JSONB NOT NULL,
    frequency   TEXT NOT NULL CHECK (frequency IN ('daily', 'weekly', 'biweekly', 'monthly', 'bimonthly', 'quarterly', 'semiannual', 'annual')),
    next_date   DATE NOT NULL,
    end_date    DATE,
    active      BOOLEAN NOT NULL DEFAULT true,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (end_date IS NULL OR end_date >= next_date OR active = false)
);
CREATE INDEX IF NOT EXISTS idx_fin_recurrences_due ON orbity.fin_recurrences (next_date) WHERE active;
COMMENT ON TABLE orbity.fin_recurrences IS 'tier:org';
ALTER TABLE orbity.fin_recurrences ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_recurrences_select_own_org" ON orbity.fin_recurrences;
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_recurrences;
CREATE POLICY "service_role_bypass" ON orbity.fin_recurrences FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON orbity.fin_recurrences FROM PUBLIC, anon, authenticated;
GRANT ALL ON orbity.fin_recurrences TO service_role;

-- Entries: payables / receivables. `overdue` is NEVER stored (computed on read). `settled_cents` is derived from unreversed settlements.
CREATE TABLE IF NOT EXISTS orbity.fin_entries (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id               UUID NOT NULL,
    direction            TEXT NOT NULL CHECK (direction IN ('payable', 'receivable')),
    status               TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'partial', 'paid', 'cancelled')),
    description          TEXT NOT NULL,
    counterparty_name    TEXT,
    counterparty_doc     TEXT,
    category_id          UUID REFERENCES orbity.fin_categories(id) ON DELETE RESTRICT,
    cost_center_id       UUID REFERENCES orbity.fin_cost_centers(id) ON DELETE RESTRICT,
    expected_account_id  UUID REFERENCES orbity.fin_accounts(id) ON DELETE RESTRICT,
    competence_month     DATE NOT NULL CHECK (EXTRACT(DAY FROM competence_month) = 1),
    due_date             DATE NOT NULL,
    amount_cents         BIGINT NOT NULL CHECK (amount_cents > 0),
    settled_cents        BIGINT NOT NULL DEFAULT 0 CHECK (settled_cents >= 0 AND settled_cents <= amount_cents),
    source               TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'recurrence', 'installment', 'commerce_order', 'contracts', 'import', 'external', 'purchasing')),
    source_ref           TEXT,
    recurrence_id        UUID REFERENCES orbity.fin_recurrences(id) ON DELETE SET NULL,
    installment_group_id UUID,
    installment_n        INTEGER,
    installment_total    INTEGER,
    notes                TEXT,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (
        (installment_group_id IS NULL AND installment_n IS NULL AND installment_total IS NULL)
        OR (installment_group_id IS NOT NULL AND installment_n BETWEEN 1 AND installment_total
            AND installment_total >= 2)
    )
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_entries_source_ref ON orbity.fin_entries (org_id, source, source_ref)
    WHERE source_ref IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_entries_recurrence_due ON orbity.fin_entries (recurrence_id, due_date)
    WHERE recurrence_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_entries_installment ON orbity.fin_entries (installment_group_id, installment_n)
    WHERE installment_group_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_fin_entries_org_due ON orbity.fin_entries (org_id, due_date);
CREATE INDEX IF NOT EXISTS idx_fin_entries_org_status ON orbity.fin_entries (org_id, status, due_date);
CREATE INDEX IF NOT EXISTS idx_fin_entries_org_competence ON orbity.fin_entries (org_id, competence_month);
CREATE INDEX IF NOT EXISTS idx_fin_entries_category ON orbity.fin_entries (category_id);
-- E21: did this sale carry a nota fiscal? NULL = not informed (the MEI report counts it as "sem nota" and warns).
ALTER TABLE orbity.fin_entries ADD COLUMN IF NOT EXISTS has_invoice BOOLEAN;
-- Entry source vocabulary: re-stated so tables created before a source existed accept it.
ALTER TABLE orbity.fin_entries DROP CONSTRAINT IF EXISTS fin_entries_source_check;
ALTER TABLE orbity.fin_entries ADD CONSTRAINT fin_entries_source_check CHECK (source IN ('manual', 'recurrence', 'installment', 'commerce_order', 'contracts', 'import', 'external', 'purchasing'));
COMMENT ON TABLE orbity.fin_entries IS 'tier:org';
ALTER TABLE orbity.fin_entries ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_entries_select_own_org" ON orbity.fin_entries;
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_entries;
CREATE POLICY "service_role_bypass" ON orbity.fin_entries FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON orbity.fin_entries FROM PUBLIC, anon, authenticated;
GRANT ALL ON orbity.fin_entries TO service_role;

-- Statement imports (slice D service). sha256 unique per account: re-importing a file is a 409.
CREATE TABLE IF NOT EXISTS orbity.fin_statement_imports (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id        UUID NOT NULL,
    account_id    UUID NOT NULL REFERENCES orbity.fin_accounts(id) ON DELETE RESTRICT,
    format        TEXT NOT NULL CHECK (format IN ('ofx', 'csv')),
    filename      TEXT NOT NULL,
    sha256        TEXT NOT NULL,
    period_start  DATE,
    period_end    DATE,
    imported_by   UUID,
    at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (account_id, sha256)
);
CREATE INDEX IF NOT EXISTS idx_fin_statement_imports_org ON orbity.fin_statement_imports (org_id, at DESC);
COMMENT ON TABLE orbity.fin_statement_imports IS 'tier:org';
ALTER TABLE orbity.fin_statement_imports ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_statement_imports_select_own_org" ON orbity.fin_statement_imports;
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_statement_imports;
CREATE POLICY "service_role_bypass" ON orbity.fin_statement_imports FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON orbity.fin_statement_imports FROM PUBLIC, anon, authenticated;
GRANT ALL ON orbity.fin_statement_imports TO service_role;

-- Statement lines (slice D service). `ledger_id` FK is added after the ledger exists (cycle).
CREATE TABLE IF NOT EXISTS orbity.fin_statement_lines (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id               UUID NOT NULL,
    import_id            UUID NOT NULL REFERENCES orbity.fin_statement_imports(id) ON DELETE CASCADE,
    account_id           UUID NOT NULL REFERENCES orbity.fin_accounts(id) ON DELETE RESTRICT,
    posted_on            DATE NOT NULL,
    amount_cents         BIGINT NOT NULL CHECK (amount_cents <> 0),
    description          TEXT NOT NULL DEFAULT '',
    fitid                TEXT NOT NULL,
    match_status         TEXT NOT NULL DEFAULT 'unmatched' CHECK (match_status IN ('unmatched', 'suggested', 'matched', 'ignored')),
    ledger_id            UUID,
    suggested_entry_id   UUID REFERENCES orbity.fin_entries(id) ON DELETE SET NULL,
    UNIQUE (account_id, fitid)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_statement_lines_ledger ON orbity.fin_statement_lines (ledger_id)
    WHERE ledger_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_fin_statement_lines_import ON orbity.fin_statement_lines (import_id);
CREATE INDEX IF NOT EXISTS idx_fin_statement_lines_org_status ON orbity.fin_statement_lines (org_id, match_status);
COMMENT ON TABLE orbity.fin_statement_lines IS 'tier:org';
ALTER TABLE orbity.fin_statement_lines ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_statement_lines_select_own_org" ON orbity.fin_statement_lines;
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_statement_lines;
CREATE POLICY "service_role_bypass" ON orbity.fin_statement_lines FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON orbity.fin_statement_lines FROM PUBLIC, anon, authenticated;
GRANT ALL ON orbity.fin_statement_lines TO service_role;

-- Settlements: payments / refunds against an entry. NEVER deleted -- a reversal sets reversed_* and books opposite ledger rows.
CREATE TABLE IF NOT EXISTS orbity.fin_settlements (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id            UUID NOT NULL,
    entry_id          UUID NOT NULL REFERENCES orbity.fin_entries(id) ON DELETE RESTRICT,
    account_id        UUID NOT NULL REFERENCES orbity.fin_accounts(id) ON DELETE RESTRICT,
    kind              TEXT NOT NULL CHECK (kind IN ('payment', 'refund')),
    settled_on        DATE NOT NULL,
    amount_cents      BIGINT NOT NULL CHECK (amount_cents > 0),
    fee_cents         BIGINT NOT NULL DEFAULT 0 CHECK (fee_cents >= 0),
    method            TEXT,
    external_ref      TEXT,
    statement_line_id UUID REFERENCES orbity.fin_statement_lines(id) ON DELETE SET NULL,
    created_by        UUID,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    reversed_at       TIMESTAMPTZ,
    reversed_by       UUID,
    reversal_reason   TEXT,
    CHECK ((reversed_at IS NULL) = (reversal_reason IS NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_settlements_external ON orbity.fin_settlements (org_id, kind, external_ref)
    WHERE external_ref IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_fin_settlements_entry ON orbity.fin_settlements (entry_id);
CREATE INDEX IF NOT EXISTS idx_fin_settlements_org_date ON orbity.fin_settlements (org_id, settled_on);
COMMENT ON TABLE orbity.fin_settlements IS 'tier:org';
ALTER TABLE orbity.fin_settlements ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_settlements_select_own_org" ON orbity.fin_settlements;
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_settlements;
CREATE POLICY "service_role_bypass" ON orbity.fin_settlements FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON orbity.fin_settlements FROM PUBLIC, anon, authenticated;
GRANT ALL ON orbity.fin_settlements TO service_role;

-- Ledger (append-only): the money that actually moved on an account. Transfers = two rows sharing transfer_group. A reversal row points at the row it reverses.
CREATE TABLE IF NOT EXISTS orbity.fin_ledger (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id         UUID NOT NULL,
    account_id     UUID NOT NULL REFERENCES orbity.fin_accounts(id) ON DELETE RESTRICT,
    occurred_on    DATE NOT NULL,
    direction      TEXT NOT NULL CHECK (direction IN ('in', 'out')),
    amount_cents   BIGINT NOT NULL CHECK (amount_cents > 0),
    origin         TEXT NOT NULL CHECK (origin IN ('settlement', 'fee', 'transfer', 'adjustment', 'opening')),
    settlement_id  UUID REFERENCES orbity.fin_settlements(id) ON DELETE RESTRICT,
    transfer_group UUID,
    reverses_id    UUID REFERENCES orbity.fin_ledger(id) ON DELETE RESTRICT,
    description    TEXT,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (origin <> 'transfer' OR transfer_group IS NOT NULL),
    CHECK (origin NOT IN ('settlement', 'fee') OR settlement_id IS NOT NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_ledger_settlement_origin ON orbity.fin_ledger (settlement_id, origin)
    WHERE settlement_id IS NOT NULL AND reverses_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_ledger_reverses ON orbity.fin_ledger (reverses_id)
    WHERE reverses_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_fin_ledger_account_date ON orbity.fin_ledger (org_id, account_id, occurred_on);
CREATE INDEX IF NOT EXISTS idx_fin_ledger_transfer ON orbity.fin_ledger (transfer_group)
    WHERE transfer_group IS NOT NULL;
DO $fin_fk$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'fin_statement_lines_ledger_id_fkey' AND conrelid = 'orbity.fin_statement_lines'::regclass
    ) THEN
        ALTER TABLE orbity.fin_statement_lines
            ADD CONSTRAINT fin_statement_lines_ledger_id_fkey
            FOREIGN KEY (ledger_id) REFERENCES orbity.fin_ledger(id) ON DELETE SET NULL;
    END IF;
END
$fin_fk$;
COMMENT ON TABLE orbity.fin_ledger IS 'tier:org';
ALTER TABLE orbity.fin_ledger ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_ledger_select_own_org" ON orbity.fin_ledger;
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_ledger;
CREATE POLICY "service_role_bypass" ON orbity.fin_ledger FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON orbity.fin_ledger FROM PUBLIC, anon, authenticated;
GRANT ALL ON orbity.fin_ledger TO service_role;

