    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (org_id, category_id, month)
);
CREATE INDEX IF NOT EXISTS idx_fin_budgets_org_month ON orbity.fin_budgets (org_id, month);
COMMENT ON TABLE orbity.fin_budgets IS 'tier:org';
ALTER TABLE orbity.fin_budgets ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_budgets_select_own_org" ON orbity.fin_budgets;
DROP POLICY IF EXISTS "service_role_bypass" ON orbity.fin_budgets;
CREATE POLICY "service_role_bypass" ON orbity.fin_budgets FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON orbity.fin_budgets FROM PUBLIC, anon, authenticated;
GRANT ALL ON orbity.fin_budgets TO service_role;

-- Settle under a row lock: the balance is checked and the settlement inserted in ONE transaction.
CREATE OR REPLACE FUNCTION orbity.fin_settle_entry_locked(p_org_id UUID, p_entry_id UUID, p_row JSONB) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, orbity, pg_temp
AS $fn$
DECLARE
    v_entry   orbity.fin_entries%ROWTYPE;
    v_row     orbity.fin_settlements%ROWTYPE;
    v_settled BIGINT;
    v_amount  BIGINT := (p_row->>'amount_cents')::BIGINT;
    v_kind    TEXT := p_row->>'kind';
BEGIN
    IF v_amount IS NULL OR v_amount <= 0 THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'valor_invalido');
    END IF;
    IF v_kind IS NULL OR v_kind NOT IN ('payment', 'refund') THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'tipo_invalido');
    END IF;
    SELECT * INTO v_entry FROM orbity.fin_entries WHERE id = p_entry_id AND org_id = p_org_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'not_found');
    END IF;
    IF v_entry.status = 'cancelled' THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'lancamento_cancelado');
    END IF;
    SELECT COALESCE(SUM(CASE WHEN kind = 'payment' THEN amount_cents ELSE -amount_cents END), 0) INTO v_settled
        FROM orbity.fin_settlements WHERE entry_id = p_entry_id AND reversed_at IS NULL;
    IF v_kind = 'payment' AND v_amount > v_entry.amount_cents - v_settled THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'baixa_excede_saldo');
    END IF;
    IF v_kind = 'refund' AND v_amount > v_settled THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'estorno_excede_pago');
    END IF;
    INSERT INTO orbity.fin_settlements
        SELECT * FROM jsonb_populate_record(
            NULL::orbity.fin_settlements,
            jsonb_set(jsonb_set(p_row, '{org_id}', to_jsonb(p_org_id::text)), '{entry_id}', to_jsonb(p_entry_id::text))
        )
        RETURNING * INTO v_row;
    RETURN jsonb_build_object('status', 'ok', 'settlement', to_jsonb(v_row));
END;
$fn$;
REVOKE ALL ON FUNCTION orbity.fin_settle_entry_locked(UUID, UUID, JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION orbity.fin_settle_entry_locked(UUID, UUID, JSONB) TO service_role;

-- Reverse under the same lock: stamp the settlement and book the opposite ledger rows atomically.
CREATE OR REPLACE FUNCTION orbity.fin_reverse_settlement_locked(p_org_id UUID, p_settlement_id UUID, p_reason TEXT, p_user UUID, p_on DATE) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, orbity, pg_temp
AS $fn$
DECLARE
    v_st      orbity.fin_settlements%ROWTYPE;
    v_entry   orbity.fin_entries%ROWTYPE;
    v_settled BIGINT;
    v_after   BIGINT;
BEGIN
    SELECT * INTO v_st FROM orbity.fin_settlements WHERE id = p_settlement_id AND org_id = p_org_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'not_found');
    END IF;
    SELECT * INTO v_entry FROM orbity.fin_entries WHERE id = v_st.entry_id AND org_id = p_org_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'settlement % has no entry in org %', p_settlement_id, p_org_id USING ERRCODE = 'P0002';
    END IF;
    SELECT * INTO v_st FROM orbity.fin_settlements WHERE id = p_settlement_id;
    IF v_st.reversed_at IS NOT NULL THEN
        RETURN jsonb_build_object('status', 'already_reversed');
    END IF;
    SELECT COALESCE(SUM(CASE WHEN kind = 'payment' THEN amount_cents ELSE -amount_cents END), 0) INTO v_settled
        FROM orbity.fin_settlements WHERE entry_id = v_entry.id AND reversed_at IS NULL;
    v_after := CASE WHEN v_st.kind = 'payment' THEN v_settled - v_st.amount_cents ELSE v_settled + v_st.amount_cents END;
    IF v_after < 0 OR v_after > v_entry.amount_cents THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'baixa_com_estorno');
    END IF;
    UPDATE orbity.fin_settlements
        SET reversed_at = now(), reversed_by = p_user, reversal_reason = p_reason
        WHERE id = p_settlement_id RETURNING * INTO v_st;
    INSERT INTO orbity.fin_ledger (org_id, account_id, occurred_on, direction, amount_cents, origin, description, settlement_id, reverses_id)
        SELECT l.org_id, l.account_id, p_on, CASE l.direction WHEN 'in' THEN 'out' ELSE 'in' END, l.amount_cents, l.origin,
               'Estorno: ' || COALESCE(l.description, ''), l.settlement_id, l.id
        FROM orbity.fin_ledger l
        WHERE l.settlement_id = p_settlement_id AND l.reverses_id IS NULL
          AND NOT EXISTS (SELECT 1 FROM orbity.fin_ledger r WHERE r.reverses_id = l.id);
    RETURN jsonb_build_object('status', 'ok', 'settlement', to_jsonb(v_st));
END;
$fn$;
REVOKE ALL ON FUNCTION orbity.fin_reverse_settlement_locked(UUID, UUID, TEXT, UUID, DATE) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION orbity.fin_reverse_settlement_locked(UUID, UUID, TEXT, UUID, DATE) TO service_role;

-- Signed ledger sum: the balance / opening-balance aggregate computed in the database (one row back, not N).
CREATE OR REPLACE FUNCTION orbity.fin_ledger_signed_sum(p_org_id UUID, p_account_id UUID, p_on DATE, p_inclusive BOOLEAN) RETURNS BIGINT
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, orbity, pg_temp
AS $fn$
DECLARE
    v_sum BIGINT;
BEGIN
    IF p_account_id IS NULL THEN
        SELECT COALESCE(SUM(CASE WHEN direction = 'in' THEN amount_cents ELSE -amount_cents END), 0)::BIGINT INTO v_sum
            FROM orbity.fin_ledger
            WHERE org_id = p_org_id AND occurred_on <= p_on AND (p_inclusive OR occurred_on < p_on);
    ELSE
        SELECT COALESCE(SUM(CASE WHEN direction = 'in' THEN amount_cents ELSE -amount_cents END), 0)::BIGINT INTO v_sum
            FROM orbity.fin_ledger
            WHERE org_id = p_org_id AND account_id = p_account_id AND occurred_on <= p_on AND (p_inclusive OR occurred_on < p_on);
    END IF;
    RETURN v_sum;
END;
$fn$;
REVOKE ALL ON FUNCTION orbity.fin_ledger_signed_sum(UUID, UUID, DATE, BOOLEAN) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION orbity.fin_ledger_signed_sum(UUID, UUID, DATE, BOOLEAN) TO service_role;

-- Private finance attachments bucket; SERVICE-ONLY (no authenticated object policy) -- the API signs access.
INSERT INTO storage.buckets (id, name, public)
VALUES ('finance-attachments', 'finance-attachments', false)
ON CONFLICT (id) DO NOTHING;
UPDATE storage.buckets SET file_size_limit = 10485760, allowed_mime_types = ARRAY['application/pdf', 'image/png', 'image/jpeg', 'image/webp', 'application/xml', 'text/xml']::text[] WHERE id = 'finance-attachments';
DROP POLICY IF EXISTS "finance-attachments_storage_select" ON storage.objects;
DROP POLICY IF EXISTS "finance-attachments_storage_insert" ON storage.objects;
DROP POLICY IF EXISTS "finance-attachments_storage_update" ON storage.objects;
DROP POLICY IF EXISTS "finance-attachments_storage_delete" ON storage.objects;
DROP POLICY IF EXISTS "finance-attachments_storage_service" ON storage.objects;
CREATE POLICY "finance-attachments_storage_service" ON storage.objects FOR ALL TO service_role
  USING (bucket_id = 'finance-attachments')
  WITH CHECK (bucket_id = 'finance-attachments');
